/// What a Dart value can be *asked*.
///
/// `x is Foo` wants to know what a value really is, and a Rust trait object
/// cannot be asked unless the trait says it can. `Any` is the mechanism; this
/// is the one line of it that every translated trait inherits, so every trait
/// object can answer.
///
/// Not a blanket impl. `Box<dyn Widget>` would then implement it *itself*, and
/// `.as_any()` would answer about the box rather than about what is in it --
/// a downcast that is always false and never says so. Each translated struct
/// gets its own one-line impl instead, so the only way to reach `as_any` from
/// a box is through the trait inside it.
/// `Object` above it: an `Rc<dyn Widget>` then unsizes to an `Rc<dyn
/// Object>` (trait upcasting), which no `impl Object for dyn Widget` could
/// give -- a coercion needs the supertrait. `as_any` is `Object`'s.
pub trait DartAny: Object + 'static {
    /// `runtimeType` reachable through a `&__Self: Trait + ?Sized` -- a super
    /// function's `this_` -- where `Object::runtime_type` would resolve on
    /// the *reference* and demand it be `'static` (E0521).
    fn dart_runtime_type(&self) -> Type;

    /// The object as one of the traits it implements, boxed as the
    /// `Rc<dyn Trait>` the caller asked for by `TypeId` (see `dart_cast_to`).
    /// Every translated struct answers for its own type and for every trait
    /// it has an `impl` for; the closed world is what makes that a list.
    fn dart_cast(&self, _target: std::any::TypeId) -> Option<Box<dyn std::any::Any>> {
        None
    }
}

/// No impl for `Rc<T>`: a method call on a handle auto-derefs to the
/// object, and a blanket impl beside `Object`'s made `as_any` ambiguous
/// (5136 E0034s the first time).
/// `x.dart_cast_to::<dyn Widget>()`: Dart's `x as Widget` and `x is Widget`
/// where `Widget` is a trait, which `Any` cannot answer (a `dyn Any` knows
/// one concrete type). A method on everything, so the receiver may be a
/// handle, a reference or a value alike.
pub trait DartCastExt {
    fn dart_cast_to<T: ?Sized + 'static>(&self) -> Option<std::rc::Rc<T>>;
}

impl<S: DartAny + ?Sized> DartCastExt for S {
    fn dart_cast_to<T: ?Sized + 'static>(&self) -> Option<std::rc::Rc<T>> {
        self.dart_cast(std::any::TypeId::of::<T>())
            .and_then(|b| b.downcast::<std::rc::Rc<T>>().ok())
            .map(|b| *b)
    }
}

/// ..through a handle, and through an absent-or-not one: `x is Foo` where
/// `x` is a `Foo?` asks the value inside, and `null is Foo` is false.
impl<S: DartCastExt + ?Sized> DartCastExt for std::rc::Rc<S> {
    fn dart_cast_to<T: ?Sized + 'static>(&self) -> Option<std::rc::Rc<T>> {
        (**self).dart_cast_to::<T>()
    }
}

impl<S: DartCastExt> DartCastExt for Option<S> {
    fn dart_cast_to<T: ?Sized + 'static>(&self) -> Option<std::rc::Rc<T>> {
        self.as_ref().and_then(|v| v.dart_cast_to::<T>())
    }
}

/// The cast table for objects reached through `dyn Object`, whose blanket
/// impl cannot know their type: `TypeId` of the struct to the function that
/// asks it `dart_cast`. Filled as objects are made -- `dart_rc`,
/// `dart_object`, and every constructor that is not `const` -- which in a
/// closed world is every object an `is Trait` can ever meet.
type DartCastFn = fn(&dyn std::any::Any, std::any::TypeId) -> Option<Box<dyn std::any::Any>>;

thread_local! {
    static DART_CASTS: std::cell::RefCell<std::collections::HashMap<std::any::TypeId, DartCastFn>> =
        std::cell::RefCell::new(std::collections::HashMap::new());
}

pub fn dart_register<T: DartAny>() {
    DART_CASTS.with(|c| {
        c.borrow_mut()
            .entry(std::any::TypeId::of::<T>())
            .or_insert(|any, t| any.downcast_ref::<T>().and_then(|v| v.dart_cast(t)));
    });
}

/// `Rc::new` for a value shared as an object: registered on the way.
pub fn dart_object<T: DartAny>(value: T) -> std::rc::Rc<T> {
    dart_register::<T>();
    std::rc::Rc::new(value)
}

impl DartCastExt for dyn Object {
    fn dart_cast_to<T: ?Sized + 'static>(&self) -> Option<std::rc::Rc<T>> {
        let any = self.as_any();
        let id = std::any::Any::type_id(any);
        let f = DART_CASTS.with(|c| c.borrow().get(&id).copied());
        f.and_then(|f| f(any, std::any::TypeId::of::<T>()))
            .and_then(|b| b.downcast::<std::rc::Rc<T>>().ok())
            .map(|b| *b)
    }
}

/// Dart's `Duration`: a signed span counted in whole microseconds.
///
/// Not `std::time::Duration`, which is unsigned and counts nanoseconds.
/// Upstream subtracts durations and checks `isNegative`, so the sign has to
/// survive, and every Dart constructor and getter is in microseconds.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Default, Hash)]
pub struct Duration {
    pub microseconds: i64,
}

impl Duration {
    /// `Duration({days, hours, minutes, seconds, milliseconds, microseconds})`,
    /// every part optional and arriving as `None` when left off.
    /// `Duration({days, hours, ..})`: every part defaults to 0 in Dart, and
    /// the front end fills the defaults in, so each arrives as a plain
    /// `i64`.
    pub fn new(
        days: i64,
        hours: i64,
        minutes: i64,
        seconds: i64,
        milliseconds: i64,
        microseconds: i64,
    ) -> Self {
        Duration {
            microseconds: days * 86_400_000_000
                + hours * 3_600_000_000
                + minutes * 60_000_000
                + seconds * 1_000_000
                + milliseconds * 1_000
                + microseconds,
        }
    }

    pub const ZERO: Duration = Duration { microseconds: 0 };

    pub const fn from_microseconds(microseconds: i64) -> Self {
        Duration { microseconds }
    }

    pub const fn from_milliseconds(milliseconds: i64) -> Self {
        Duration {
            microseconds: milliseconds * 1000,
        }
    }

    pub const fn from_seconds(seconds: i64) -> Self {
        Duration {
            microseconds: seconds * 1000000,
        }
    }

    /// Truncating, like Dart's: `inMilliseconds` of 1500us is 1, not 2.
    pub fn in_microseconds(&self) -> i64 {
        self.microseconds
    }

    pub fn in_milliseconds(&self) -> i64 {
        self.microseconds / 1000
    }

    pub fn in_seconds(&self) -> i64 {
        self.microseconds / 1000000
    }

    pub fn in_minutes(&self) -> i64 {
        self.microseconds / 60000000
    }

    pub fn in_hours(&self) -> i64 {
        self.microseconds / 3600000000
    }

    pub fn in_days(&self) -> i64 {
        self.microseconds / 86400000000
    }

    pub fn is_negative(&self) -> bool {
        self.microseconds < 0
    }

    pub fn abs(&self) -> Duration {
        Duration {
            microseconds: self.microseconds.abs(),
        }
    }

    pub fn compare_to(&self, other: Duration) -> i64 {
        match self.microseconds.cmp(&other.microseconds) {
            std::cmp::Ordering::Less => -1,
            std::cmp::Ordering::Equal => 0,
            std::cmp::Ordering::Greater => 1,
        }
    }
}

impl std::ops::Add for Duration {
    type Output = Duration;
    fn add(self, other: Duration) -> Duration {
        Duration {
            microseconds: self.microseconds + other.microseconds,
        }
    }
}

impl std::ops::Sub for Duration {
    type Output = Duration;
    fn sub(self, other: Duration) -> Duration {
        Duration {
            microseconds: self.microseconds - other.microseconds,
        }
    }
}

impl std::ops::Neg for Duration {
    type Output = Duration;
    fn neg(self) -> Duration {
        Duration {
            microseconds: -self.microseconds,
        }
    }
}

impl std::ops::Mul<i64> for Duration {
    type Output = Duration;
    fn mul(self, by: i64) -> Duration {
        Duration {
            microseconds: self.microseconds * by,
        }
    }
}

impl fmt::Display for Duration {
    /// Dart prints `0:00:01.500000`.
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        let us = self.microseconds.abs();
        if self.microseconds < 0 {
            write!(f, "-")?;
        }
        write!(
            f,
            "{}:{:02}:{:02}.{:06}",
            us / 3600000000,
            (us / 60000000) % 60,
            (us / 1000000) % 60,
            us % 1000000
        )
    }
}

/// Dart's `StringBuffer`.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct StringBuffer {
    text: String,
}

impl StringBuffer {
    /// `StringBuffer([content = ''])`: the optional start, which the front
    /// end always supplies.
    pub fn new(content: String) -> Self {
        StringBuffer { text: content }
    }

    pub fn write<T: fmt::Display>(&mut self, value: T) {
        self.text.push_str(&value.to_string());
    }

    pub fn writeln<T: fmt::Display>(&mut self, value: T) {
        self.text.push_str(&value.to_string());
        self.text.push('\n');
    }

    pub fn write_char_code(&mut self, code: i64) {
        if let Some(c) = char::from_u32(code as u32) {
            self.text.push(c);
        }
    }

    pub fn clear(&mut self) {
        self.text.clear();
    }

    pub fn length(&self) -> i64 {
        self.text.chars().count() as i64
    }

    pub fn is_empty(&self) -> bool {
        self.text.is_empty()
    }

    pub fn is_not_empty(&self) -> bool {
        !self.text.is_empty()
    }
}

impl fmt::Display for StringBuffer {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

/// Dart's `Set`, backed by a `Vec`.
///
/// Not `HashSet`: Dart puts `double`s and objects with no `hashCode` of their
/// own into sets, and requiring `Hash + Eq` here would refuse code that is
/// perfectly ordinary in Dart. Membership is therefore linear, which is the
/// right trade for a translation -- correct first, and the sets upstream keeps
/// are small.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Set<T> {
    items: Vec<T>,
}

impl<T: Clone> Set<T> {
    /// `LinkedHashSet.of(elements)` / `Set.of(elements)`.
    pub fn new() -> Self {
        Set { items: Vec::new() }
    }

    pub fn clear(&mut self) {
        self.items.clear();
    }

    pub fn length(&self) -> i64 {
        self.items.len() as i64
    }

    pub fn is_empty(&self) -> bool {
        self.items.is_empty()
    }

    pub fn is_not_empty(&self) -> bool {
        !self.items.is_empty()
    }

    pub fn to_list(&self) -> Vec<T> {
        self.items.clone()
    }

    pub fn iter(&self) -> std::slice::Iter<'_, T> {
        self.items.iter()
    }
}

impl<T: PartialEq + Clone> Set<T> {
    pub fn of(elements: Vec<T>) -> Set<T> {
        let mut s = Set::new();
        for e in elements {
            s.add(e);
        }
        s
    }

    pub fn from(items: Vec<T>) -> Self {
        let mut set = Set::new();
        for item in items {
            set.add(item);
        }
        set
    }

    /// Dart returns whether the value was new.
    pub fn add(&mut self, value: T) -> bool {
        if self.contains(&value) {
            return false;
        }
        self.items.push(value);
        true
    }

    pub fn add_all(&mut self, values: Vec<T>) {
        for value in values {
            self.add(value);
        }
    }

    pub fn contains(&self, value: &T) -> bool {
        self.items.iter().any(|item| item == value)
    }

    pub fn remove(&mut self, value: &T) -> bool {
        match self.items.iter().position(|item| item == value) {
            Some(at) => {
                self.items.remove(at);
                true
            }
            None => false,
        }
    }

    pub fn union(&self, other: &Set<T>) -> Set<T> {
        let mut out = self.clone();
        out.add_all(other.to_list());
        out
    }

    pub fn intersection(&self, other: &Set<T>) -> Set<T> {
        Set {
            items: self
                .items
                .iter()
                .filter(|item| other.contains(item))
                .cloned()
                .collect(),
        }
    }

    pub fn difference(&self, other: &Set<T>) -> Set<T> {
        Set {
            items: self
                .items
                .iter()
                .filter(|item| !other.contains(item))
                .cloned()
                .collect(),
        }
    }
}

impl<T> IntoIterator for Set<T> {
    type Item = T;
    type IntoIter = std::vec::IntoIter<T>;
    fn into_iter(self) -> Self::IntoIter {
        self.items.into_iter()
    }
}

/// Dart's `StackTrace`.
///
/// Opaque on purpose. Dart's is captured by the runtime at the point a throw
/// happens, and there is no runtime here to capture one; what upstream does
/// with it is print it or pass it along, and both work with a string that says
/// so honestly.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct StackTrace {
    text: String,
}

impl StackTrace {
    /// `StackTrace.fromString(text)` and `_StringStackTrace(text)`.
    pub fn new(text: String) -> Self {
        StackTrace { text }
    }

    pub fn empty() -> Self {
        StackTrace {
            text: String::new(),
        }
    }

    pub fn current() -> Self {
        StackTrace {
            text: "<no stack trace: translated from Dart>".to_string(),
        }
    }
}

impl fmt::Display for StackTrace {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

/// Dart's `DateTime`: an instant, counted in microseconds from the epoch.
///
/// `now()` is the one thing here that needs the outside world, and it uses the
/// system clock. Dart's is the same clock. `isUtc` is carried because upstream
/// compares on it, and the arithmetic ignores it exactly as Dart's does --
/// a `Duration` is a span, not a calendar step.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Default, Hash)]
pub struct DateTime {
    pub microseconds_since_epoch: i64,
    pub is_utc: bool,
}

impl DateTime {
    /// `isUtc`, the field, as the method every other getter here is (a
    /// Dart field of a `dart:` class is read as a call, see the front end).
    pub fn is_utc(&self) -> bool {
        self.is_utc
    }

    /// Days since the epoch and the microseconds into that day, UTC.
    fn civil(&self) -> (i64, i64) {
        let day = 86_400_000_000i64;
        let days = self.microseconds_since_epoch.div_euclid(day);
        let rest = self.microseconds_since_epoch.rem_euclid(day);
        (days, rest)
    }

    /// Howard Hinnant's civil-from-days: (year, month, day).
    fn ymd(&self) -> (i64, i64, i64) {
        let (z, _) = self.civil();
        let z = z + 719_468;
        let era = z.div_euclid(146_097);
        let doe = z - era * 146_097;
        let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
        let y = yoe + era * 400;
        let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
        let mp = (5 * doy + 2) / 153;
        let d = doy - (153 * mp + 2) / 5 + 1;
        let m = if mp < 10 { mp + 3 } else { mp - 9 };
        (if m <= 2 { y + 1 } else { y }, m, d)
    }

    /// `DateTime(year, [month, day, hour, minute, second, millisecond,
    /// microsecond])`: local time is UTC here (no zone database yet).
    pub fn new(
        year: i64,
        month: i64,
        day: i64,
        hour: i64,
        minute: i64,
        second: i64,
        millisecond: i64,
        microsecond: i64,
    ) -> Self {
        // Hinnant's days-from-civil.
        let y = if month <= 2 { year - 1 } else { year };
        let era = y.div_euclid(400);
        let yoe = y - era * 400;
        let mp = if month > 2 { month - 3 } else { month + 9 };
        let doy = (153 * mp + 2) / 5 + day - 1;
        let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
        let days = era * 146_097 + doe - 719_468;
        let micros = ((((days * 24 + hour) * 60 + minute) * 60 + second) * 1000 + millisecond)
            * 1000
            + microsecond;
        DateTime {
            microseconds_since_epoch: micros,
            is_utc: false,
        }
    }

    /// `DateTime.utc(..)`: the same arithmetic, marked UTC.
    pub fn utc(
        year: i64,
        month: i64,
        day: i64,
        hour: i64,
        minute: i64,
        second: i64,
        millisecond: i64,
        microsecond: i64,
    ) -> Self {
        let mut t = DateTime::new(
            year,
            month,
            day,
            hour,
            minute,
            second,
            millisecond,
            microsecond,
        );
        t.is_utc = true;
        t
    }

    pub fn year(&self) -> i64 {
        self.ymd().0
    }
    pub fn month(&self) -> i64 {
        self.ymd().1
    }
    pub fn day(&self) -> i64 {
        self.ymd().2
    }
    pub fn hour(&self) -> i64 {
        self.civil().1 / 3_600_000_000
    }
    pub fn minute(&self) -> i64 {
        self.civil().1 / 60_000_000 % 60
    }
    pub fn second(&self) -> i64 {
        self.civil().1 / 1_000_000 % 60
    }
    pub fn millisecond(&self) -> i64 {
        self.civil().1 / 1_000 % 1_000
    }
    pub fn microsecond(&self) -> i64 {
        self.civil().1 % 1_000
    }
    /// `compareTo(other)`: by the instant.
    pub fn compare_to(&self, other: DateTime) -> i64 {
        self.microseconds_since_epoch
            .cmp(&other.microseconds_since_epoch) as i64
    }

    /// `timeZoneOffset`: local time is UTC here, so zero.
    pub fn time_zone_offset(&self) -> Duration {
        Duration { microseconds: 0 }
    }

    /// `weekday`: Monday is 1, Sunday 7, as `DateTime.monday..sunday`.
    pub fn weekday(&self) -> i64 {
        let (days, _) = self.civil();
        (days + 3).rem_euclid(7) + 1
    }

    pub fn now() -> Self {
        let since = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_micros() as i64)
            .unwrap_or(0);
        DateTime {
            microseconds_since_epoch: since,
            is_utc: false,
        }
    }

    pub fn from_microseconds_since_epoch(microseconds: i64) -> Self {
        DateTime {
            microseconds_since_epoch: microseconds,
            is_utc: false,
        }
    }

    pub fn from_milliseconds_since_epoch(milliseconds: i64) -> Self {
        DateTime {
            microseconds_since_epoch: milliseconds * 1000,
            is_utc: false,
        }
    }

    pub fn milliseconds_since_epoch(&self) -> i64 {
        self.microseconds_since_epoch / 1000
    }

    pub fn difference(&self, other: DateTime) -> Duration {
        Duration {
            microseconds: self.microseconds_since_epoch - other.microseconds_since_epoch,
        }
    }

    pub fn add(&self, span: Duration) -> DateTime {
        DateTime {
            microseconds_since_epoch: self.microseconds_since_epoch + span.microseconds,
            is_utc: self.is_utc,
        }
    }

    pub fn subtract(&self, span: Duration) -> DateTime {
        DateTime {
            microseconds_since_epoch: self.microseconds_since_epoch - span.microseconds,
            is_utc: self.is_utc,
        }
    }

    pub fn is_before(&self, other: DateTime) -> bool {
        self.microseconds_since_epoch < other.microseconds_since_epoch
    }

    pub fn is_after(&self, other: DateTime) -> bool {
        self.microseconds_since_epoch > other.microseconds_since_epoch
    }
}

/// A value that belongs to one isolate, standing in a Rust `static`.
///
/// Dart's `static` is one **per isolate**, and an isolate is a thread. Rust's
/// `static` is one per *process*, so what it holds must be `Sync` -- and a
/// `Box<dyn Fn(..)>`, which is what half of Flutter's statics hold, is not and
/// never will be.
///
/// `thread_local!` says the same thing safely, and would be the right answer if
/// its value could be reached without a closure; it cannot, and
/// `Box<dyn Fn(..)>` is not `Clone`, so every read would have to be
/// restructured. This says it instead, and the `unsafe` is carrying exactly
/// one claim:
///
/// **the translated program runs on one thread.**
///
/// That is true of a Dart isolate by construction, and it is the thing to
/// check before running anything translated here: the moment this program
/// spawns a thread that touches a static, this is unsound. Nothing translated
/// so far can spawn one -- `Isolate.spawn` and `compute` are not translated --
/// and if that changes, this is where it breaks.
pub struct Isolate<T>(pub T);

unsafe impl<T> Sync for Isolate<T> {}
unsafe impl<T> Send for Isolate<T> {}

impl<T> std::ops::Deref for Isolate<T> {
    type Target = T;
    fn deref(&self) -> &T {
        &self.0
    }
}

impl<T> std::ops::DerefMut for Isolate<T> {
    fn deref_mut(&mut self) -> &mut T {
        &mut self.0
    }
}

/// `dart:core`'s "no argument was passed" marker.
///
/// Upstream's `copyWith` methods take a sentinel as the default so that
/// passing `null` and passing nothing can be told apart. What is done with it
/// is compare identities, so an empty struct says everything it says -- and it
/// is `Copy`, which is what makes the comparison free.
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, Hash)]
pub struct SentinelValue;

/// An object's own handle, from inside.
///
/// A trait's default body has `&self` and no `Rc`; Dart's `this` there is a
/// value that can be stored and returned (`return this` in `TextScaler.clamp`).
/// Every counted struct keeps a weak back-reference to its own `Rc`, set the
/// moment the `Rc` is made (`dart_rc`), and a trait reaches it through
/// `dart_self_<trait>()`. A clone starts empty: a new handle around a copy is
/// a new object.
pub struct DartSelf<T: ?Sized>(std::cell::OnceCell<std::rc::Weak<T>>);

impl<T: ?Sized> DartSelf<T> {
    pub const fn new() -> Self {
        DartSelf(std::cell::OnceCell::new())
    }

    pub fn set(&self, rc: &std::rc::Rc<T>) {
        let _ = self.0.set(std::rc::Rc::downgrade(rc));
    }

    pub fn get(&self) -> std::rc::Rc<T> {
        self.0
            .get()
            .and_then(|w| w.upgrade())
            .expect("dart2rust: `this` taken before the object had a handle")
    }
}

impl<T: ?Sized> Clone for DartSelf<T> {
    fn clone(&self) -> Self {
        DartSelf::new()
    }
}

impl<T: ?Sized> Default for DartSelf<T> {
    fn default() -> Self {
        DartSelf::new()
    }
}

impl<T: ?Sized> std::fmt::Debug for DartSelf<T> {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("DartSelf")
    }
}

impl<T: ?Sized> PartialEq for DartSelf<T> {
    fn eq(&self, _: &Self) -> bool {
        true
    }
}

/// The struct's back-reference, for `dart_rc`.
pub trait DartSelfRef {
    fn dart_self_ref(&self) -> &DartSelf<Self>;
}

/// `std::rc::Rc::new` for a counted object: the handle is made and remembered.
pub fn dart_rc<T: DartSelfRef + DartAny>(value: T) -> std::rc::Rc<T> {
    dart_register::<T>();
    let rc = std::rc::Rc::new(value);
    rc.dart_self_ref().set(&rc);
    rc
}

/// Dart's `MapEntry`.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct MapEntry<K, V> {
    pub key: K,
    pub value: V,
}

impl<K, V> MapEntry<K, V> {
    pub fn new(key: K, value: V) -> Self {
        MapEntry { key, value }
    }
}

/// Dart's `Map`: a lookup that **keeps insertion order**.
///
/// A Dart map literal is a `LinkedHashMap`, and `keys`, `values`, `entries`
/// and `forEach` walk it in the order things were put in. A
/// `std::collections::HashMap` does not, so those five members were refused --
/// 97 of them -- rather than reorder anything quietly.
///
/// A `Vec` of pairs keeps the order and costs a linear lookup. That is the
/// same trade `Set<T>` next door has always made, and taking it here too
/// makes one decision instead of two: whatever these containers cost, they
/// cost it the same way.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Map<K, V> {
    entries: Vec<(K, V)>,
}

/// What needs no key equality: a `Map<Rc<dyn Fn()>, i64>` -- Dart's
/// `ObserverList` -- can be made and sized, and only the lookups on it
/// want the keys comparable (43 holders' constructors at ws298).
impl<K: Clone, V: Clone> Map<K, V> {
    /// `Map.of(other)`: a copy with the same entries, in the same order.
    pub fn of(other: Map<K, V>) -> Map<K, V> {
        other
    }
    pub fn new() -> Self {
        Map {
            entries: Vec::new(),
        }
    }

    pub fn clear(&mut self) {
        self.entries.clear();
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    pub fn len(&self) -> usize {
        self.entries.len()
    }

    /// In insertion order, which is the whole reason for this type.
    pub fn keys(&self) -> Vec<K> {
        self.entries.iter().map(|(k, _)| k.clone()).collect()
    }

    pub fn values(&self) -> Vec<V> {
        self.entries.iter().map(|(_, v)| v.clone()).collect()
    }

    pub fn entries(&self) -> Vec<MapEntry<K, V>> {
        self.entries
            .iter()
            .map(|(k, v)| MapEntry {
                key: k.clone(),
                value: v.clone(),
            })
            .collect()
    }

    pub fn for_each(
        &self,
        mut f: impl FnMut(K, V) -> Result<(), DartError>,
    ) -> Result<(), DartError> {
        for (key, value) in &self.entries {
            f(key.clone(), value.clone())?;
        }
        Ok(())
    }
}

impl<K: PartialEq + Clone, V: Clone> Map<K, V> {
    pub fn from<const N: usize>(items: [(K, V); N]) -> Self {
        let mut map = Map::new();
        for (key, value) in items {
            map.insert(key, value);
        }
        map
    }

    fn at(&self, key: &K) -> Option<usize> {
        self.entries.iter().position(|(k, _)| k == key)
    }

    pub fn get(&self, key: &K) -> Option<&V> {
        self.at(key).map(|i| &self.entries[i].1)
    }

    /// Dart gives back what was there; so does Rust's `HashMap::insert`.
    /// Replacing a value keeps the key where it was, which is what insertion
    /// order means once a key is written twice.
    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
        match self.at(&key) {
            Some(i) => Some(std::mem::replace(&mut self.entries[i].1, value)),
            None => {
                self.entries.push((key, value));
                None
            }
        }
    }

    pub fn contains_key(&self, key: &K) -> bool {
        self.at(key).is_some()
    }

    pub fn remove(&mut self, key: &K) -> Option<V> {
        self.at(key).map(|i| self.entries.remove(i).1)
    }

    /// Dart's `putIfAbsent`: the value that is there afterwards, either way.
    pub fn put_if_absent(
        &mut self,
        key: K,
        make: impl FnOnce() -> Result<V, DartError>,
    ) -> Result<V, DartError> {
        if let Some(i) = self.at(&key) {
            return Ok(self.entries[i].1.clone());
        }
        let value = make()?;
        self.entries.push((key, value.clone()));
        Ok(value)
    }

    pub fn extend(&mut self, other: Map<K, V>) {
        for (key, value) in other.entries {
            self.insert(key, value);
        }
    }
}

impl<K, V> IntoIterator for Map<K, V> {
    type Item = (K, V);
    type IntoIter = std::vec::IntoIter<(K, V)>;
    fn into_iter(self) -> Self::IntoIter {
        self.entries.into_iter()
    }
}

/// `dart:collection`'s public map and set classes.
///
/// Dart's `LinkedHashMap` keeps insertion order and `HashMap` does not. Both
/// are the ordered `Map` here: keeping an order nothing asked for is a
/// promise too strong, never one too weak. `SplayTreeMap` is sorted, and
/// `BTreeMap` would be the same promise -- it is not translated.
pub type LinkedHashMap<K, V> = Map<K, V>;
pub type HashMap<K, V> = Map<K, V>;
pub type LinkedHashSet<T> = Set<T>;
pub type HashSet<T> = Set<T>;

/// Dart's `Queue` and its two concrete kinds, backed by a `VecDeque`.
///
/// `LinkedList` in Dart is an intrusive list -- its elements carry their own
/// links -- and a `VecDeque` is not that. Nothing translated so far uses the
/// intrusive part, and this is where to look if something does.
pub type Queue<T> = std::collections::VecDeque<T>;

/// `Future.then(onValue, {onError})` on the `Pin<Box<dyn Future>>` a Dart
/// `Future<T>` is here: the continuation runs when the future does. The
/// error path has nothing to catch yet -- a Dart throw is not a Rust
/// value on this side -- so `onError` is carried and never called.
pub trait DartFuture<T> {
    fn then<R: 'static>(
        self,
        on_value: std::rc::Rc<dyn Fn(T) -> Result<R, DartError>>,
        on_error: Option<std::rc::Rc<dyn Fn(DartError) -> Result<R, DartError>>>,
    ) -> std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = Result<R, DartError>>>>;
}

/// `future.then(onValue, onError: ..)`: a translated future completes with
/// a `Result`; the error goes to `onError` when there is one, and on
/// through the returned future when there is not.
impl<T: 'static> DartFuture<T>
    for std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = Result<T, DartError>>>>
{
    fn then<R: 'static>(
        self,
        on_value: std::rc::Rc<dyn Fn(T) -> Result<R, DartError>>,
        on_error: Option<std::rc::Rc<dyn Fn(DartError) -> Result<R, DartError>>>,
    ) -> std::pin::Pin<std::boxed::Box<dyn std::future::Future<Output = Result<R, DartError>>>>
    {
        std::boxed::Box::pin(async move {
            match self.await {
                Ok(value) => on_value(value),
                Err(error) => match on_error {
                    Some(handler) => handler(error),
                    None => Err(error),
                },
            }
        })
    }
}

/// A `dynamic message` parameter: a `String`, an `Option` of one, or nothing.
pub trait IntoMessage {
    fn into_message(self) -> String;
}

impl IntoMessage for String {
    fn into_message(self) -> String {
        self
    }
}

/// `ArgumentError(other)` with an object for its message: printed as
/// Dart would print it (`Instance of 'X'`, or the class's own text).
impl<T: ?Sized + std::fmt::Debug> IntoMessage for std::rc::Rc<T> {
    fn into_message(self) -> String {
        format!("{:?}", self)
    }
}

impl IntoMessage for &str {
    fn into_message(self) -> String {
        self.to_string()
    }
}

impl IntoMessage for Option<String> {
    fn into_message(self) -> String {
        self.unwrap_or_default()
    }
}

impl IntoMessage for Option<std::rc::Rc<dyn Object>> {
    fn into_message(self) -> String {
        self.map(|o| format!("{:?}", o)).unwrap_or_default()
    }
}

/// Equality by identity for what is shared: what Dart's `Object.==` does,
/// and what a derived `PartialEq` over an `Rc<dyn X>` field cannot say
/// (see `_emitStruct`).
pub trait DartEq {
    fn dart_eq(&self, other: &Self) -> bool;
}

impl<T: ?Sized> DartEq for std::rc::Rc<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        std::rc::Rc::ptr_eq(self, other)
    }
}

impl<T: DartEq> DartEq for Option<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Some(a), Some(b)) => a.dart_eq(b),
            (None, None) => true,
            _ => false,
        }
    }
}

impl<T: DartEq> DartEq for Vec<T> {
    fn dart_eq(&self, other: &Self) -> bool {
        self.len() == other.len() && self.iter().zip(other.iter()).all(|(a, b)| a.dart_eq(b))
    }
}

/// `hashCode` of a shared object: its identity, as Dart's `Object.hashCode`.
pub trait RcHashCode {
    fn hash_code(&self) -> i64;
}

impl<T: ?Sized> RcHashCode for std::rc::Rc<T> {
    fn hash_code(&self) -> i64 {
        (std::rc::Rc::as_ptr(self) as *const u8 as usize as i64) & 0x3fff_ffff
    }
}

/// `int.parse(s)`: Dart's, which throws a `FormatException` on anything else.
pub fn parse_int(text: String) -> i64 {
    match try_parse_int(text.clone()) {
        Some(v) => v,
        None => panic!(
            "uncaught Dart exception: FormatException: Invalid radix-10 number: {}",
            text
        ),
    }
}

/// `int.tryParse(s)`: an optional sign and decimal digits, or `0x` hex.
pub fn try_parse_int(text: String) -> Option<i64> {
    let t = text.trim();
    let (neg, body) = match t.strip_prefix('-') {
        Some(rest) => (true, rest),
        None => (false, t.strip_prefix('+').unwrap_or(t)),
    };
    let v = if let Some(hex) = body.strip_prefix("0x").or_else(|| body.strip_prefix("0X")) {
        i64::from_str_radix(hex, 16).ok()?
    } else {
        if body.is_empty() || !body.bytes().all(|b| b.is_ascii_digit()) {
            return None;
        }
        body.parse::<i64>().ok()?
    };
    Some(if neg { -v } else { v })
}

/// `double.parse(s)`.
pub fn parse_double(text: String) -> f64 {
    match try_parse_double(text.clone()) {
        Some(v) => v,
        None => panic!(
            "uncaught Dart exception: FormatException: Invalid double {}",
            text
        ),
    }
}

/// `double.tryParse(s)`: Dart's grammar is close enough to Rust's here;
/// `Infinity`/`NaN` spellings are the difference and are mapped.
pub fn try_parse_double(text: String) -> Option<f64> {
    let t = text.trim();
    match t {
        "Infinity" | "+Infinity" => return Some(f64::INFINITY),
        "-Infinity" => return Some(f64::NEG_INFINITY),
        "NaN" => return Some(f64::NAN),
        _ => {}
    }
    if t.is_empty() || t.starts_with("inf") || t.starts_with("nan") {
        return None;
    }
    t.parse::<f64>().ok()
}

/// `null.hashCode` is a fixed number in Dart; an absent value hashes to it.
impl<T: RcHashCode> RcHashCode for Option<T> {
    fn hash_code(&self) -> i64 {
        match self {
            Some(v) => v.hash_code(),
            None => 2011,
        }
    }
}

/// `Queue`'s own methods, by their Dart names.
pub trait DartQueue<T> {
    fn length(&self) -> i64;
    fn remove_first(&mut self) -> T;
    fn remove_last(&mut self) -> T;
    fn add_first(&mut self, value: T);
    fn add_last(&mut self, value: T);
}

impl<T> DartQueue<T> for std::collections::VecDeque<T> {
    fn length(&self) -> i64 {
        self.len() as i64
    }
    fn remove_first(&mut self) -> T {
        self.pop_front().expect("removeFirst on an empty Queue")
    }
    fn remove_last(&mut self) -> T {
        self.pop_back().expect("removeLast on an empty Queue")
    }
    fn add_first(&mut self, value: T) {
        self.push_front(value)
    }
    fn add_last(&mut self, value: T) {
        self.push_back(value)
    }
}
pub type ListQueue<T> = std::collections::VecDeque<T>;
pub type DoubleLinkedQueue<T> = std::collections::VecDeque<T>;
pub type LinkedList<T> = std::collections::VecDeque<T>;

/// Dart's `Stopwatch`.
///
/// Real, and the one other thing here that reaches the outside world: it uses
/// the monotonic clock, as Dart's does. `elapsedTicks` is microseconds, and
/// `frequency` says so, which is what Dart reports on every platform Flutter
/// ships to.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Stopwatch {
    started: Option<std::time::Instant>,
    accumulated: u128,
}

impl Default for Stopwatch {
    fn default() -> Self {
        Stopwatch::new()
    }
}

impl Stopwatch {
    pub const FREQUENCY: i64 = 1000000;

    pub fn new() -> Self {
        Stopwatch {
            started: None,
            accumulated: 0,
        }
    }

    pub fn start(&mut self) {
        if self.started.is_none() {
            self.started = Some(std::time::Instant::now());
        }
    }

    pub fn stop(&mut self) {
        if let Some(at) = self.started.take() {
            self.accumulated += at.elapsed().as_micros();
        }
    }

    pub fn reset(&mut self) {
        self.accumulated = 0;
        if self.started.is_some() {
            self.started = Some(std::time::Instant::now());
        }
    }

    pub fn is_running(&self) -> bool {
        self.started.is_some()
    }

    pub fn elapsed_microseconds(&self) -> i64 {
        let running = self.started.map(|at| at.elapsed().as_micros()).unwrap_or(0);
        (self.accumulated + running) as i64
    }

    pub fn elapsed_milliseconds(&self) -> i64 {
        self.elapsed_microseconds() / 1000
    }

    pub fn elapsed(&self) -> Duration {
        Duration {
            microseconds: self.elapsed_microseconds(),
        }
    }
}

/// Dart's `Uri`, as far as upstream uses one.
///
/// The whole text, plus the pieces that can be taken from it without a parser
/// worth the name. Upstream builds asset keys and compares them; it does not
/// resolve relative references here, and `resolve` is left out rather than
/// written wrong. `parse` never fails, which Dart's does -- another reason not
/// to reach for this where correctness of the parse matters.
#[derive(Clone, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct Uri {
    pub text: String,
}

impl Uri {
    pub fn parse(text: String) -> Self {
        Uri { text }
    }

    /// `isScheme(scheme)`: case-insensitively.
    /// `Uri.encodeFull(s)`: percent-encodes what a full URI may not hold.
    pub fn encode_full(text: String) -> String {
        let mut out = String::new();
        for b in text.bytes() {
            let keep = b.is_ascii_alphanumeric() || b"-._~:/?#[]@!$&'()*+,;=%".contains(&b);
            if keep {
                out.push(b as char)
            } else {
                out.push_str(&format!("%{:02X}", b))
            }
        }
        out
    }

    pub fn is_scheme(&self, scheme: String) -> bool {
        self.scheme().eq_ignore_ascii_case(&scheme)
    }

    /// `host`: the authority's host, or empty.
    pub fn host(&self) -> String {
        let rest = match self.text.find("://") {
            Some(at) => &self.text[at + 3..],
            None => return String::new(),
        };
        let end = rest
            .find(|c| c == '/' || c == '?' || c == '#')
            .unwrap_or(rest.len());
        let authority = &rest[..end];
        let host = authority.rsplit('@').next().unwrap_or(authority);
        host.split(':').next().unwrap_or("").to_string()
    }

    pub fn scheme(&self) -> String {
        match self.text.find(':') {
            Some(at) if !self.text[..at].contains('/') => self.text[..at].to_string(),
            _ => String::new(),
        }
    }

    /// `fragment`: what follows `#`, or empty.
    pub fn fragment(&self) -> String {
        match self.text.find('#') {
            Some(i) => self.text[i + 1..].to_string(),
            None => String::new(),
        }
    }

    /// `query`: between `?` and `#`, or empty.
    pub fn query(&self) -> String {
        let end = self.text.find('#').unwrap_or(self.text.len());
        match self.text[..end].find('?') {
            Some(i) => self.text[i + 1..end].to_string(),
            None => String::new(),
        }
    }

    /// `queryParametersAll`: every value under each key, in order.
    pub fn query_parameters_all(&self) -> Map<String, Vec<String>> {
        let mut out: Map<String, Vec<String>> = Map::new();
        let query = self.query();
        if query.is_empty() {
            return out;
        }
        for pair in query.split('&') {
            let (k, v) = match pair.find('=') {
                Some(i) => (&pair[..i], &pair[i + 1..]),
                None => (pair, ""),
            };
            let key = Uri::decode_query_component(k.to_string());
            let value = Uri::decode_query_component(v.to_string());
            let mut values = out.get(&key).cloned().unwrap_or_default();
            values.push(value);
            out.insert(key, values);
        }
        out
    }

    /// `queryParameters`: the first value under each key.
    pub fn query_parameters(&self) -> Map<String, String> {
        let mut out: Map<String, String> = Map::new();
        for (k, vs) in self.query_parameters_all().into_iter() {
            if let Some(v) = vs.first() {
                out.insert(k, v.clone());
            }
        }
        out
    }

    /// `Uri.decodeQueryComponent(s)`: `+` is a space, `%XX` a byte.
    pub fn decode_query_component(text: String) -> String {
        Uri::decode_component(text.replace('+', " "))
    }

    /// `Uri.decodeComponent(s)`: `%XX` a byte.
    pub fn decode_component(text: String) -> String {
        let bytes = text.as_bytes();
        let mut out = Vec::new();
        let mut i = 0;
        while i < bytes.len() {
            if bytes[i] == b'%' && i + 2 < bytes.len() {
                if let Ok(b) = u8::from_str_radix(&text[i + 1..i + 3], 16) {
                    out.push(b);
                    i += 3;
                    continue;
                }
            }
            out.push(bytes[i]);
            i += 1;
        }
        String::from_utf8_lossy(&out).into_owned()
    }

    pub fn path(&self) -> String {
        let rest = match self.text.find("://") {
            Some(at) => &self.text[at + 3..],
            None => &self.text[..],
        };
        let rest = match rest.find('/') {
            Some(at) => &rest[at..],
            None => rest,
        };
        rest.split(['?', '#']).next().unwrap_or("").to_string()
    }

    pub fn path_segments(&self) -> Vec<String> {
        self.path()
            .split('/')
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect()
    }

    pub fn has_scheme(&self) -> bool {
        !self.scheme().is_empty()
    }
}

impl fmt::Display for Uri {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.text)
    }
}

