/// The `List` methods a `Vec` does not have under Dart's meaning.
///
/// `remove(value)` in Dart removes the first equal element and reports whether
/// there was one; `Vec::remove` takes an index. `sort(compare)` takes a
/// comparator returning an `int`, which Rust wants as an `Ordering`. The
/// elements are cloned into the comparator because the translated closure
/// takes Dart's `T`, not Rust's `&T` -- the same trade the iterator chains
/// make, written here once instead of at every call.
pub trait DartList<T> {
    /// `length`, under its Dart name, beside `len()`.
    fn length(&self) -> i64;
    /// `sublist(start, [end])`: a copy of that range.
    fn sublist(&self, start: i64, end: Option<i64>) -> Vec<T>;
    /// `sort([compare])`: without one, the elements' own order.
    fn sort_by_dart(
        &mut self,
        compare: Option<std::rc::Rc<dyn Fn(T, T) -> Result<i64, DartError>>>,
    ) -> Result<(), DartError>;
    /// `firstWhere(test)`: panics like Dart's `StateError` when none matches.
    fn first_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<T, DartError>;
    /// `firstWhere(test, orElse: f)`.
    fn first_where_or<F: Fn(T) -> Result<bool, DartError>, G: Fn() -> Result<T, DartError>>(
        &self,
        test: F,
        or_else: G,
    ) -> Result<T, DartError>;
    /// `setRange(start, end, from, skip)`: copies `from[skip..]` over
    /// `self[start..end]`.
    fn set_range(&mut self, start: i64, end: i64, from: Vec<T>, skip: i64);
    /// `skip(n)`/`take(n)`, collected.
    fn skip_dart(&self, n: i64) -> Vec<T>;
    fn take_dart(&self, n: i64) -> Vec<T>;
}

impl<T: Clone> DartList<T> for Vec<T> {
    fn length(&self) -> i64 {
        self.len() as i64
    }

    fn sublist(&self, start: i64, end: Option<i64>) -> Vec<T> {
        let s = (start.max(0) as usize).min(self.len());
        let e = end
            .map(|n| (n.max(0) as usize).min(self.len()))
            .unwrap_or(self.len());
        self[s..e.max(s)].to_vec()
    }

    fn sort_by_dart(
        &mut self,
        compare: Option<std::rc::Rc<dyn Fn(T, T) -> Result<i64, DartError>>>,
    ) -> Result<(), DartError> {
        // `sort_by` cannot stop early: the first error is kept, the rest of
        // the sort runs on `Equal`, and the error is returned after.
        let failed: std::cell::RefCell<Option<DartError>> = std::cell::RefCell::new(None);
        match compare {
            Some(f) => self.sort_by(|a, b| match f(a.clone(), b.clone()) {
                Ok(x) if x < 0 => std::cmp::Ordering::Less,
                Ok(0) => std::cmp::Ordering::Equal,
                Ok(_) => std::cmp::Ordering::Greater,
                Err(e) => {
                    if failed.borrow().is_none() {
                        *failed.borrow_mut() = Some(e);
                    }
                    std::cmp::Ordering::Equal
                }
            }),
            None => panic!("List.sort() without a comparator on a type with no natural order here"),
        }
        match failed.into_inner() {
            Some(e) => Err(e),
            None => Ok(()),
        }
    }

    fn first_where<F: Fn(T) -> Result<bool, DartError>>(&self, test: F) -> Result<T, DartError> {
        for x in self.iter() {
            if test(x.clone())? {
                return Ok(x.clone());
            }
        }
        panic!("Bad state: No element")
    }

    fn first_where_or<F: Fn(T) -> Result<bool, DartError>, G: Fn() -> Result<T, DartError>>(
        &self,
        test: F,
        or_else: G,
    ) -> Result<T, DartError> {
        for x in self.iter() {
            if test(x.clone())? {
                return Ok(x.clone());
            }
        }
        or_else()
    }

    fn set_range(&mut self, start: i64, end: i64, from: Vec<T>, skip: i64) {
        let (start, end, skip) = (start as usize, end as usize, skip as usize);
        self[start..end].clone_from_slice(&from[skip..skip + (end - start)]);
    }

    fn skip_dart(&self, n: i64) -> Vec<T> {
        self.iter().skip(n.max(0) as usize).cloned().collect()
    }
    fn take_dart(&self, n: i64) -> Vec<T> {
        self.iter().take(n.max(0) as usize).cloned().collect()
    }
}

/// The `List` methods that compare elements, apart so that a `Vec<T>`
/// with only `T: Clone` (a generic class's `T`, 2026-09-04) still has
/// `set_range` and `sublist`; `remove(value)` and `indexOf` ask for
/// `==` and are an error at the use when `T` has none.
pub trait DartListEq<T> {
    fn remove_value(&mut self, value: T) -> bool;
    /// `indexOf(value)`: the first index holding an equal element, or -1.
    fn index_of(&self, value: T) -> i64;
}

impl<T: PartialEq + Clone> DartListEq<T> for Vec<T> {
    fn remove_value(&mut self, value: T) -> bool {
        match self.iter().position(|x| *x == value) {
            Some(i) => {
                self.remove(i);
                true
            }
            None => false,
        }
    }
    fn index_of(&self, value: T) -> i64 {
        match self.iter().position(|x| *x == value) {
            Some(i) => i as i64,
            None => -1,
        }
    }
}

